; c04_alu_cmp -- ALU CMP.EQ / NE / LT / GE and BR.COND ALU_CMP_TRUE
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: the numeric codes of cmp_op (D1); signed_mode of a compare; the ALU_CMP_TRUE branch condition
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c04_alu_cmp.expected.csv
.include "conf_defs.inc"
.main
    MOV CONST(0x0005, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0009, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU CMP.EQ unsigned
    BR.COND ALU_CMP_TRUE, yes0
    EXEC_CSR WRITE8 RES + 0, 0x00
    JMP next0
yes0:
    EXEC_CSR WRITE8 RES + 0, 0x01
next0:
    ALU CMP.NE unsigned
    BR.COND ALU_CMP_TRUE, yes1
    EXEC_CSR WRITE8 RES + 1, 0x00
    JMP next1
yes1:
    EXEC_CSR WRITE8 RES + 1, 0x01
next1:
    ALU CMP.LT unsigned
    BR.COND ALU_CMP_TRUE, yes2
    EXEC_CSR WRITE8 RES + 2, 0x00
    JMP next2
yes2:
    EXEC_CSR WRITE8 RES + 2, 0x01
next2:
    ALU CMP.GE unsigned
    BR.COND ALU_CMP_TRUE, yes3
    EXEC_CSR WRITE8 RES + 3, 0x00
    JMP next3
yes3:
    EXEC_CSR WRITE8 RES + 3, 0x01
next3:
    MOV CONST(0x0009, 2) -> MAIN_SCRATCHPAD[0..1]
